std::complex<double> A53(int j1, int j2, int j3, int j4, int j5, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb, double mtsq) {

  double s12 = s(j1, j2);
  double s45 = s(j1, j2) + s(j2, j3) + s(j3, j1);
  const bool tandbtogether=true, largemassexp=false;
  auto kinstructure = two * zb(j5, j3) * zb(j3, j1) * za(j2, j4) / s45;
  std::complex<double> A53_res = czip;

  if (tandbtogether) {
    A53_res = -kinstructure * L1(-s12, -s45) / two / s45;
  }

  if (mtsq == 0.0) {
    A53_res = kinstructure * L1(-s12, -s45) / two / s45;
  } else {
    if (largemassexp) {
      A53_res = A53_res + kinstructure / (24.0 * mtsq) * 
                (1.0 + (2.0 * s12 + s45) / 15.0 / mtsq * zip +
                 (2.0 * s12 * s45 + 3.0 * s12 * s12 + s45 * s45) / 140.0 / (mtsq * mtsq) * zip);
    } else {
      double musq = mtsq;
      A53_res = A53_res + kinstructure * F1anom(s12, s45, mtsq, musq);
    }
  }

  return A53_res;
}

